/// Unlit cell. A saver that wants a cell dark still paints it.
pub const BLANK: u16 = 0;
/// Every pixel lit — a whole cell of one colour.
pub const SOLID: u16 = 1;
/// A small centred square, U+25AA. One lit lamp with dark margin all
/// round, so a run of adjacent cells reads as separate lights.
pub const BLOCK: u16 = 54;

/// Block Elements — two halves, four three-quarters and a 50% shade,
/// this repo's own bitmaps rather than the .hex's: on an 8x16 cell each
/// is an exact rectangle. U+2588 FULL BLOCK is `SOLID` above. A sprite
/// drawn from these reads as pixel art, not line art, and a half block
/// is a square 8x8 pixel in an 8x16 cell.
pub const UPPER: u16 = 170; // U+2580 ▀
pub const LOWER: u16 = 371; // U+2584 ▄
pub const SHADE: u16 = 398; // U+2592 ▒
pub const NO_LR: u16 = 238; // U+259B ▛
pub const NO_LL: u16 = 330; // U+259C ▜
pub const NO_UR: u16 = 374; // U+2599 ▙
pub const NO_UL: u16 = 395; // U+259F ▟

